import React from 'react';

function Experience() {
  const experiences = [
    {
      title: 'Senior Frontend Developer',
      company: 'Tech Solutions Inc.',
      duration: 'Jan 2022 - Present',
      description: [
        'Led the development of a new customer-facing dashboard using React and Redux, improving user engagement by 25%.',
        'Implemented responsive UI designs, ensuring seamless experience across desktop and mobile devices.',
        'Collaborated with backend teams to integrate RESTful APIs and optimize data fetching.',
        'Mentored junior developers and conducted code reviews to maintain high code quality.'
      ]
    },
    {
      title: 'Frontend Developer',
      company: 'Web Innovations Ltd.',
      duration: 'Jul 2019 - Dec 2021',
      description: [
        'Developed and maintained various features for a large-scale e-commerce platform using Angular and TypeScript.',
        'Optimized website performance, reducing page load times by 15% through code splitting and lazy loading.',
        'Participated in agile development cycles, contributing to sprint planning and daily stand-ups.'
      ]
    },
    {
      title: 'Junior UI Developer',
      company: 'Creative Designs Agency',
      duration: 'Aug 2017 - Jun 2019',
      description: [
        'Assisted in the creation of user interfaces for client projects using HTML, CSS, and JavaScript.',
        'Converted PSD designs into pixel-perfect, responsive web pages.',
        'Learned and applied best practices in UI/UX design and frontend development.'
      ]
    }
  ];

  const education = [
    {
      degree: 'Bachelor of Technology in Computer Science',
      institution: 'Anna University',
      duration: '2013 - 2017',
      description: 'Focused on software development, data structures, and algorithms.'
    }
  ];

  return (
    <section id="experience" className="py-20 bg-gray-900 text-white">
      <div className="container mx-auto px-4">
        <h2 className="text-4xl font-bold text-center mb-12 text-blue-400">Experience & Education</h2>

        <div className="mb-16">
          <h3 className="text-3xl font-semibold text-center mb-8 text-blue-300">Experience</h3>
          <div className="relative border-l-4 border-gray-700 ml-4 md:ml-8">
            {experiences.map((exp, index) => (
              <div key={index} className="mb-10 ml-6 relative">
                <div className="absolute w-4 h-4 bg-blue-500 rounded-full -left-8 top-1 border-2 border-gray-900"></div>
                <p className="text-gray-400 text-sm">{exp.duration}</p>
                <h4 className="text-xl font-semibold text-white mt-1">{exp.title} at {exp.company}</h4>
                <ul className="list-disc list-inside text-gray-300 mt-2 space-y-1">
                  {exp.description.map((item, idx) => (
                    <li key={idx}>{item}</li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>

        <div>
          <h3 className="text-3xl font-semibold text-center mb-8 text-blue-300">Education</h3>
          <div className="relative border-l-4 border-gray-700 ml-4 md:ml-8">
            {education.map((edu, index) => (
              <div key={index} className="mb-10 ml-6 relative">
                <div className="absolute w-4 h-4 bg-blue-500 rounded-full -left-8 top-1 border-2 border-gray-900"></div>
                <p className="text-gray-400 text-sm">{edu.duration}</p>
                <h4 className="text-xl font-semibold text-white mt-1">{edu.degree} from {edu.institution}</h4>
                <p className="text-gray-300 mt-2">{edu.description}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

export default Experience;
